INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (170, 324, 'Polyester based Thermal Lamination Film', '../', '<p></p><h2> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Polyester based Thermal Lamination Film</span> </h2> <p><b><span style=''font-family:"";''></span></b><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></b></p> <p style="text-align:justify;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">PROFILE </span></b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: It is polyester based, both sides corona treated, uniformly extrusion coated with adhesive which enables lamination by heat and pressure with paper products.</span></span></p> <p style="text-align:justify;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></p> <p><b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">FEATURES</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">:</span></span></b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"></span></p> <p style="text-indent:-21.75pt;"> <span style=''font-family:"";''><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1)</span></span></span><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Fibre-tear bond strength with paper</span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2) Excellent optical properties. </span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">3) Excellent resistance to elongation &amp; tear.</span></span></p> <p><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4) Offer increased productivity with simple operation.</span></span></p> <p></p> <p><b><span style=''font-family:"";''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">APPLICATIONS :</span></span></b><span style=''font-family:"font-size:11pt;''><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thermal lamination with all kinds of printed &amp; unprinted paper and paper boards like maps, book covers,</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">posters, magazines, boxes, brochures etc.</span></span></p> <p></p> <p><span style=''font-family:"";''></span></p> <p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">TYPICAL PROPERTIES:</span></b></p> <table border="1" cellpadding="0" cellspacing="0" style="margin:auto auto auto 9.9pt;border:currentColor;border-collapse:collapse;" width="600"> <tbody> <tr> <td style="border:1pt solid windowtext;background-color:transparent;" valign="top" width="216"> <p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>PROPERTY</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="150"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>UNIT</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="126"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>ASTM/ TEST #</span></span></b></p> </td> <td style="background-color:transparent;" valign="top" width="108"> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>30 PCT-2</span></span></b></p> <p align="center" style="text-align:center;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>(PDL)</span></span></b></p> </td> </tr> <tr> <td style="background-color:transparent;" valign="top" width="216"> <p><br/></p><p><b><span style="color:#E53333;font-family:Tahoma;font-size:18px;">PHYSICAL DATA</span></b></p> <p><span style="c