enter;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">-----</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">gardner</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p><span style=''font-family:"font-size:11pt;''><sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">O</span></sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">C</span></span></p> <p></p> </td> <td style="background-color:transparent;" valign="top" width="126"> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-374-C</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">---</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">--</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-2578</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-1894</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">D-2457</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> </td> <td style="background-color:transparent;" valign="top" width="108"> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">30.0</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">34.80</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">28.73</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">40</span></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">0.25</span></p> <p align="center" style="text-align:center;"></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">95</span></p> <p align="center" style="text-align:center;"> <b></b></p> <p></p> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">90 - 150</span></p> </td> </tr> </tbody> </table> <p><b></b></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">_____________________________________________________________</span></p> <p></p>', '2026-09-06 20:58:45');